"""Export checked local SQL/worker and physical-replication evidence. Preserve raw bytes."""
import argparse,gzip,hashlib,json,pathlib,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1]
PROFILES=['middleware-fixed','proxy-fixed','middleware-adaptive','proxy-adaptive'];POLICIES=['disabled','fixed','pool'];PHASES=['healthy','workers','pool-exhaustion','recovery']
def main():
 p=argparse.ArgumentParser();p.add_argument('--report',type=pathlib.Path,required=True);a=p.parse_args();raw=a.report.read_bytes();d=json.loads(raw)
 assert d.get('passed') and len(d['runs'])==36 and len(d['replication'])==4 and all(r['passed'] for r in d['runs']+d['replication']);rows=[]
 for profile in PROFILES:
  for policy in POLICIES:
   runs=[r for r in d['runs'] if r['profile']==profile and r['policy']==policy];assert {r['repeat'] for r in runs}=={1,2,3}
   for phase in PHASES:
    phases=[next(p for p in r['phases'] if p['name']==phase) for r in runs];traffic=[p['traffic']['critical'] for p in phases];sent=sum(t['sent'] for t in traffic);waits=sum(p['pool_wait_count'] for p in phases);waitsec=sum(p['pool_wait_seconds'] for p in phases)
    vals=lambda key:[t[key] for t in traffic if t[key] is not None]
    rows.append({'profile':profile,'policy':policy,'phase':phase,'sent':sent,'success_rps':statistics.median(t['successful']/p['seconds'] for t,p in zip(traffic,phases)),'timely_rps':statistics.median(vals('successful_within_100ms_per_offered_second')),'p95_ms':statistics.median(vals('successful_p95_ms')) if vals('successful_p95_ms') else None,'rejected_percent':sum(t['rejected_503'] for t in traffic)/sent*100,'errors_percent':sum(t['backend_5xx'] for t in traffic)/sent*100,'mean_pool_wait_ms':waitsec/waits*1000 if waits else 0,'jobs_completed':statistics.median(p['jobs']['completed'] for p in phases),'jobs_rejected':statistics.median(p['jobs']['rejected'] for p in phases),'jobs_dropped':statistics.median(p['jobs']['dropped'] for p in phases),'jobs_canceled':sum(p['jobs']['canceled'] for p in phases),'jobs_failed':sum(p['jobs']['failed'] for p in phases)})
 summary={'source_sha256':hashlib.sha256(raw).hexdigest(),'sent':sum(p['sent'] for r in d['runs'] for p in r['phases']),'runs':36,'replication_profiles':4,'checks':sum(len(r['checks']) for r in d['runs']+d['replication']),'missed':sum(p['dropped_schedules'] for r in d['runs'] for p in r['phases']),'transport_errors':sum(t['transport_errors'] for r in d['runs'] for p in r['phases'] for t in p['traffic'].values()),'rows':rows,'replication':[{'profile':r['profile'],'passed':r['passed'],'checks':len(r['checks']),'replay_recovery_seconds':r['replay_recovery_seconds'],'offline_recovery_seconds':r['offline_recovery_seconds'],'idle_lag_bytes':next(e for e in r['events'] if e['phase']=='idle')['state']['replication']['LagBytes'],'paused_lag_bytes':next(e for e in r['events'] if e['phase']=='paused-backlog')['state']['replication']['LagBytes']} for r in d['replication']]}
 out=ROOT/'public/data';(out/'operation-results.json').write_bytes(raw);(out/'operation-results.json.gz').write_bytes(gzip.compress(raw,mtime=0));(ROOT/'src/data/operations-benchmark.json').write_text(json.dumps(summary,indent=2)+'\n')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'text.color':'#dae8df','axes.labelcolor':'#bccfc2','xtick.color':'#a9bfb0','ytick.color':'#cbdcd1','axes.edgecolor':'#45604f','figure.facecolor':'#101b16','axes.facecolor':'#101b16','savefig.facecolor':'#101b16'})
 colors={'disabled':'#829d8e','fixed':'#bdab79','pool':'#76d9bc'}
 for phase,title in [('workers','When worker jobs compete with transactions'),('pool-exhaustion','When external work occupies 3 of 4 SQL connections')]:
  fig,axes=plt.subplots(1,3,figsize=(17,8));selected=[r for r in rows if r['phase']==phase];labels=[r['profile'].replace('middleware-','Middleware / ').replace('proxy-','Proxy / ')+' · '+r['policy'] for r in selected]
  for ax,key,label in zip(axes,['timely_rps','p95_ms','rejected_percent'],['Critical successes within 100 ms / sec','Successful-request p95 · ms','Critical requests rejected · %']):
   ax.barh(range(len(selected)),[r[key] or 0 for r in selected],color=[colors[r['policy']] for r in selected],height=.65);ax.invert_yaxis();ax.set_yticks(range(len(selected)),labels if ax is axes[0] else []);ax.set_xlabel(label);ax.grid(axis='x',alpha=.12);ax.set_axisbelow(True);ax.spines[['top','right']].set_visible(False)
  axes[0].axvline(120,color='#bbd6c6',linestyle='--',linewidth=1);axes[0].set_xlim(0,125);axes[2].set_xlim(0,100)
  fig.suptitle(title,fontsize=17,x=.035,ha='left',y=.97);fig.text(.035,.025,'Real PostgreSQL · critical HTTP load: 120/sec · background jobs: 200 offered/sec, 6 workers, queue 16\nThree repeats per deployment/policy. Rates and successful p95 are medians; rejection percentages pool all requests.\nRead deadline responses, SQL waiting and job completions/rejections/drops in the table. Limits are per engine/process.',fontsize=10,color='#a9bfb0');fig.tight_layout(rect=(.01,.12,1,.92));fig.savefig(ROOT/f'public/images/operation-{phase}.png',dpi=150);plt.close(fig)
 fig,axes=plt.subplots(2,1,figsize=(14,8));r=next(x for x in d['runs'] if x['profile']=='middleware-fixed' and x['policy']=='pool' and x['repeat']==1);trace=r['trace'];ts=[v['seconds'] for v in trace]
 axes[0].plot(ts,[v['storage']['Active'] for v in trace],label='SQL permits in use',color='#76d9bc');axes[0].plot(ts,[v['pool']['InUse'] for v in trace],label='Pool connections in use',color='#bdab79');axes[0].axhline(4,color='#829d8e',linestyle='--');axes[0].set_ylabel('Concurrent work / connections');axes[0].legend(frameon=False,labelcolor='#dae8df');axes[1].plot(ts,[v['queue_length'] for v in trace],label='Queued fixture jobs',color='#76d9bc');axes[1].plot(ts,[v['worker']['Active'] for v in trace],label='Worker callbacks',color='#bdab79');axes[1].set_ylabel('Jobs');axes[1].set_xlabel('Seconds from start · one fixed-middleware / pool-aware run');axes[1].legend(frameon=False,labelcolor='#dae8df')
 for ax in axes:ax.grid(alpha=.12);ax.spines[['top','right']].set_visible(False)
 fig.suptitle('HTTP responses are only one layer of work',x=.06,ha='left',fontsize=17);fig.text(.06,.02,'Sampled about every 100 ms. External SQL holders occupy real connections without taking SQL permits.\nShort transients may be missed; admitted work drains after submissions stop. Raw traces retain every sample and phase.',fontsize=10,color='#a9bfb0');fig.tight_layout(rect=(.01,.09,1,.94));fig.savefig(ROOT/'public/images/operation-lifetimes.png',dpi=150);plt.close(fig)
 (out/'operation-chart-provenance.json').write_text(json.dumps({'source_sha256':summary['source_sha256'],'aggregation':'Median per-run critical throughput, timely throughput and successful p95 (not merged global percentile). Pooled rejection/error percentages. Mean SQL wait is total WaitDuration delta / WaitCount delta, including drain. Job counts are median per phase including drain. Lifetime trace is one named run, sampled about100ms.','limitations':'Short local experiments on one macOS host/Podman VM; not production capacity, OOM prevention, engine-native PostgreSQL enforcement or cluster coordination. Pool signals can oscillate and sampled values can miss transients. Three outside consumers leave one real connection; a SQL admission ceiling of4 still permits waiting even with background restricted. Driver completion is not proof server execution stopped after ambiguous network failure.','matplotlib':matplotlib.__version__,'images':['operation-workers.png','operation-pool-exhaustion.png','operation-lifetimes.png']},indent=2)+'\n');print(summary['sent'],'requests;',summary['checks'],'checks',flush=True)
if __name__=='__main__':main()
